using Modeller.Core;
namespace Modeller.Database;
internal static class CatalogueSql
{
    // Only base tables and declared keys. View/procedure semantics require separately reviewed API contracts.
    public static string Columns(string dialect)=>dialect switch {
        "sqlserver"=>"SELECT s.name AS c_schema,t.name AS c_table,c.column_id AS c_ordinal,c.name AS c_name,ty.name AS c_type,CAST(c.is_nullable AS int) AS c_null,CAST(c.is_computed AS int) AS c_computed,COALESCE(pk.key_ordinal,0) AS c_key FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.system_type_id AND ty.user_type_id=ty.system_type_id OUTER APPLY (SELECT ic.key_ordinal FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id WHERE i.object_id=t.object_id AND i.is_primary_key=1 AND ic.column_id=c.column_id) pk WHERE t.is_ms_shipped=0 AND t.is_external=0",
        "postgresql"=>"SELECT n.nspname AS c_schema,t.relname AS c_table,a.attnum AS c_ordinal,a.attname AS c_name,ty.typname AS c_type,CASE WHEN a.attnotnull THEN 'NO' ELSE 'YES' END AS c_null,CASE WHEN a.attgenerated<>'' THEN 'YES' ELSE 'NO' END AS c_computed,COALESCE(array_position(pk.conkey,a.attnum),0) AS c_key FROM pg_class t JOIN pg_namespace n ON n.oid=t.relnamespace JOIN pg_attribute a ON a.attrelid=t.oid JOIN pg_type ty ON ty.oid=a.atttypid LEFT JOIN pg_constraint pk ON pk.conrelid=t.oid AND pk.contype='p' WHERE t.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped AND has_column_privilege(t.oid,a.attnum,'SELECT')",
        "mysql" or "mariadb"=>"SELECT c.TABLE_SCHEMA AS c_schema,c.TABLE_NAME AS c_table,c.ORDINAL_POSITION AS c_ordinal,c.COLUMN_NAME AS c_name,c.DATA_TYPE AS c_type,c.IS_NULLABLE AS c_null,CASE WHEN c.EXTRA LIKE '%GENERATED%' THEN 'YES' ELSE 'NO' END AS c_computed,COALESCE(k.ORDINAL_POSITION,0) AS c_key FROM information_schema.COLUMNS c JOIN information_schema.TABLES t ON t.TABLE_SCHEMA=c.TABLE_SCHEMA AND t.TABLE_NAME=c.TABLE_NAME LEFT JOIN information_schema.KEY_COLUMN_USAGE k ON k.TABLE_SCHEMA=c.TABLE_SCHEMA AND k.TABLE_NAME=c.TABLE_NAME AND k.COLUMN_NAME=c.COLUMN_NAME AND k.CONSTRAINT_NAME='PRIMARY' WHERE t.TABLE_TYPE='BASE TABLE' AND t.ENGINE='InnoDB'",
        "oracle"=>"SELECT c.OWNER AS c_schema,c.TABLE_NAME AS c_table,c.COLUMN_ID AS c_ordinal,c.COLUMN_NAME AS c_name,c.DATA_TYPE AS c_type,c.NULLABLE AS c_null,c.VIRTUAL_COLUMN AS c_computed,NVL(pk.POSITION,0) AS c_key FROM ALL_TAB_COLS c JOIN ALL_TABLES t ON t.OWNER=c.OWNER AND t.TABLE_NAME=c.TABLE_NAME LEFT JOIN (SELECT cc.OWNER,cc.TABLE_NAME,cc.COLUMN_NAME,cc.POSITION FROM ALL_CONSTRAINTS k JOIN ALL_CONS_COLUMNS cc ON cc.OWNER=k.OWNER AND cc.CONSTRAINT_NAME=k.CONSTRAINT_NAME WHERE k.CONSTRAINT_TYPE='P' AND k.STATUS='ENABLED' AND k.VALIDATED='VALIDATED') pk ON pk.OWNER=c.OWNER AND pk.TABLE_NAME=c.TABLE_NAME AND pk.COLUMN_NAME=c.COLUMN_NAME WHERE c.HIDDEN_COLUMN='NO' AND t.TEMPORARY='N'",
        "sap-hana"=>"SELECT c.SCHEMA_NAME AS c_schema,c.TABLE_NAME AS c_table,c.POSITION AS c_ordinal,c.COLUMN_NAME AS c_name,c.DATA_TYPE_NAME AS c_type,c.IS_NULLABLE AS c_null,CASE WHEN c.GENERATED_ALWAYS_AS IS NULL THEN 'NO' ELSE 'YES' END AS c_computed,COALESCE(pk.POSITION,0) AS c_key FROM SYS.TABLE_COLUMNS c JOIN SYS.TABLES t ON t.SCHEMA_NAME=c.SCHEMA_NAME AND t.TABLE_NAME=c.TABLE_NAME LEFT JOIN SYS.CONSTRAINTS pk ON pk.SCHEMA_NAME=c.SCHEMA_NAME AND pk.TABLE_NAME=c.TABLE_NAME AND pk.COLUMN_NAME=c.COLUMN_NAME AND pk.IS_PRIMARY_KEY='TRUE' WHERE t.IS_SYSTEM_TABLE='FALSE' AND t.TABLE_TYPE IN ('ROW','COLUMN') AND t.IS_TEMPORARY='FALSE'",
        _=>throw new ProcessingException("SOURCE_DIALECT_UNKNOWN")};
    public static string Keys(string dialect)=>dialect switch {
        "sqlserver"=>"SELECT SCHEMA_NAME(t.schema_id) AS c_schema,k.name,t.name,a.name,SCHEMA_NAME(u.schema_id),u.name,b.name,c.constraint_column_id,CAST(k.is_disabled AS int),CAST(k.is_not_trusted AS int) FROM sys.foreign_keys k JOIN sys.foreign_key_columns c ON c.constraint_object_id=k.object_id JOIN sys.tables t ON t.object_id=k.parent_object_id JOIN sys.tables u ON u.object_id=k.referenced_object_id JOIN sys.columns a ON a.object_id=t.object_id AND a.column_id=c.parent_column_id JOIN sys.columns b ON b.object_id=u.object_id AND b.column_id=c.referenced_column_id",
        "postgresql"=>"SELECT ns.nspname AS c_schema,k.conname,t.relname,a.attname,nt.nspname,u.relname,b.attname,p.i,0,CASE WHEN k.convalidated THEN 0 ELSE 1 END FROM pg_constraint k JOIN pg_class t ON t.oid=k.conrelid JOIN pg_namespace ns ON ns.oid=t.relnamespace JOIN pg_class u ON u.oid=k.confrelid JOIN pg_namespace nt ON nt.oid=u.relnamespace CROSS JOIN LATERAL generate_subscripts(k.conkey,1) p(i) JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=k.conkey[p.i] JOIN pg_attribute b ON b.attrelid=u.oid AND b.attnum=k.confkey[p.i] WHERE k.contype='f'",
        "mysql" or "mariadb"=>"SELECT k.TABLE_SCHEMA AS c_schema,k.CONSTRAINT_NAME,k.TABLE_NAME,k.COLUMN_NAME,k.REFERENCED_TABLE_SCHEMA,k.REFERENCED_TABLE_NAME,k.REFERENCED_COLUMN_NAME,k.ORDINAL_POSITION,0,0 FROM information_schema.KEY_COLUMN_USAGE k WHERE k.REFERENCED_TABLE_NAME IS NOT NULL",
        "oracle"=>"SELECT k.OWNER AS c_schema,k.CONSTRAINT_NAME,k.TABLE_NAME,a.COLUMN_NAME,u.OWNER,u.TABLE_NAME,b.COLUMN_NAME,a.POSITION,CASE WHEN k.STATUS='ENABLED' THEN 0 ELSE 1 END,CASE WHEN k.VALIDATED='VALIDATED' THEN 0 ELSE 1 END FROM ALL_CONSTRAINTS k JOIN ALL_CONS_COLUMNS a ON a.OWNER=k.OWNER AND a.CONSTRAINT_NAME=k.CONSTRAINT_NAME JOIN ALL_CONSTRAINTS u ON u.OWNER=k.R_OWNER AND u.CONSTRAINT_NAME=k.R_CONSTRAINT_NAME JOIN ALL_CONS_COLUMNS b ON b.OWNER=u.OWNER AND b.CONSTRAINT_NAME=u.CONSTRAINT_NAME AND b.POSITION=a.POSITION WHERE k.CONSTRAINT_TYPE='R'",
        "sap-hana"=>"SELECT SCHEMA_NAME AS c_schema,CONSTRAINT_NAME,TABLE_NAME,COLUMN_NAME,REFERENCED_SCHEMA_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME,POSITION,CASE WHEN IS_ENFORCED='TRUE' THEN 0 ELSE 1 END,CASE WHEN IS_VALIDATED='TRUE' THEN 0 ELSE 1 END FROM SYS.REFERENTIAL_CONSTRAINTS",
        _=>throw new ProcessingException("SOURCE_DIALECT_UNKNOWN")};
}
